SINA_SMART["bacterio1-enterobacteria-2"] = {"lecture":"bacterio1-enterobacteria-2","title":"Enterobacteriaceae II: Salmonella, Enterobacter and Proteus","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-enterobacteria-2:e0","text":"Salmonella: motile, lactose −, H₂S +, oxidase −, urease −; black-centred colonies.","topic":"Salmonella","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e1","text":"Typhi/Paratyphi: humans only; non-typhoidal: zoonotic (eggs, poultry).","topic":"Salmonella","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e2","text":"Typhoid: invasion → macrophages → bacteraemia; gallbladder carriers.","topic":"Typhoid fever","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e3","text":"Typhoid: sustained fever; blood culture 80-90% positive in week 1.","topic":"Typhoid fever","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e4","text":"Complications: intestinal haemorrhage and perforation.","topic":"Typhoid fever","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e5","text":"Treatment: fluoroquinolone, ceftriaxone or azithromycin; vaccines Ty21a (oral) and Vi (injectable).","topic":"Typhoid fever","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e6","text":"Enterobacter cloacae / K. aerogenes: ICU opportunists with AmpC.","topic":"Enterobacter cloacae and Klebsiella aerogenes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e7","text":"AmpC: resistance to ampicillin, co-amoxiclav, C1G, C2G; carbapenems for severe.","topic":"Enterobacter cloacae and Klebsiella aerogenes","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e8","text":"Proteus: swarming, urease +, non-lactose fermenter.","topic":"Proteus","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-enterobacteria-2:e9","text":"Urease → alkaline urine → struvite stones, catheter blockage.","topic":"Proteus","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1dvhmzh":"a","xqwrr9":"a","d8kxbj":"a","iymyvn":"a","12b8z1a":"a","138xbhp":"a","19ebp51":"a","pfeofc":"a","1hv9tad":"a","bqdppo":"a","efr5xx":"a","1sxzda9":"a","7yop8u":"a","h5n407":"a","1esrv6a":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-enterobacteria-2:e0":{"s":0,"u":["Salmonella: motile, lactose −, H₂S +, oxidase −, urease −; black-centred colonies.","Salmonella are Gram-negative, non-capsulated (except the Vi antigen of Typhi) bacilli, mostly motile , non-sporing; glucose fermenting, H₂S positive , nitrate reductase positive, oxidase and urease negative , lactose negative ; facultative anaerobes growing at 37-42 °C.","On Hektoen, XLD, SS or bismuth sulphite agar they form colourless colonies with black H₂S centres ."],"dp":[]},"bacterio1-enterobacteria-2:e1":{"s":0,"u":["Typhi/Paratyphi: humans only; non-typhoidal: zoonotic (eggs, poultry).","Non-typhoidal serovars: zoonotic , from undercooked eggs, poultry, meat, dairy or contaminated vegetables, causing gastroenteritis , usually self-limited.","Typhi, Paratyphi): strictly human , faecal-oral, about 22 million cases a year worldwide, endemic and travel-related; about 1 in 20 infected people becomes an asymptomatic carrier."],"dp":[]},"bacterio1-enterobacteria-2:e2":{"s":1,"u":["Typhoid: invasion → macrophages → bacteraemia; gallbladder carriers.","Pathogenesis : resistance to stomach acid and bile, adhesion and invasion of intestinal cells via the type III secretion system , survival in macrophages , bacteraemia and spread to liver, spleen and bone marrow; the Vi capsule and LPS aid survival; chronic gallbladder carriers keep shedding bacteria."],"dp":[{"h":"Typhoid Mary and the carrier state","t":"Mary Mallon, a cook in New York in the early 1900s, was healthy but carried S. Typhi in her gallbladder and infected dozens of people through the food she prepared. She became the classic example of the asymptomatic chronic carrier described in this lecture: bacteria shelter in the gallbladder, often around gallstones, and are shed in stool for years. This is why food handlers are screened, why typhoid is a notifiable disease and why carriers may need prolonged antibiotics or even cholecystectomy. Source: history of public health; the lecture's carrier state."}]},"bacterio1-enterobacteria-2:e3":{"s":1,"u":["Typhoid: sustained fever; blood culture 80-90% positive in week 1.","Diagnosis : blood culture in the first week (80-90% positive before antibiotics), then stool, urine, bile or clot cultures; biochemical identification; slide agglutination with antisera; serology (Widal test, ELISA) of limited value.","Symptoms appear 1-3 weeks after exposure: sustained high fever (39-40 °C), headache, abdominal pain, lethargy, anorexia, swollen abdomen, rash (rose spots), constipation or diarrhoea."],"dp":[]},"bacterio1-enterobacteria-2:e4":{"s":1,"u":["Complications: intestinal haemorrhage and perforation.","Complications: intestinal bleeding and perforation ; untreated, fever lasts weeks to months and mortality can reach 30%."],"dp":[]},"bacterio1-enterobacteria-2:e5":{"s":1,"u":["Treatment: fluoroquinolone, ceftriaxone or azithromycin; vaccines Ty21a (oral) and Vi (injectable).","Treatment : fluoroquinolones (ciprofloxacin), ceftriaxone or cefixime, or azithromycin , adapted to resistance; rehydration, rest, hospital care for severe cases.","Vaccines : oral live attenuated Ty21a (4 capsules, from 6 years, booster every 5 years) and injectable Vi polysaccharide (1 dose, from 2 years, booster every 2-3 years)."],"dp":[]},"bacterio1-enterobacteria-2:e6":{"s":2,"u":["Enterobacter cloacae / K. aerogenes: ICU opportunists with AmpC.","Enterobacter aerogenes has been renamed Klebsiella aerogenes for its genetic closeness to Klebsiella ; it has a more prominent capsule, stronger biofilm and outbreak potential.","Both are classic ICU opportunists : UTIs, pneumonia, bacteraemia and wound infections, spread by hands, catheters, ventilators and contaminated fluids."],"dp":[]},"bacterio1-enterobacteria-2:e7":{"s":2,"u":["AmpC: resistance to ampicillin, co-amoxiclav, C1G, C2G; carbapenems for severe.","Their key feature is a chromosomal AmpC β-lactamase : intrinsic resistance to ampicillin, amoxicillin-clavulanate and first- and second-generation cephalosporins, with a risk of selecting AmpC-overproducing mutants under third-generation cephalosporins.","Treatment is guided by susceptibility testing: cefepime or piperacillin-tazobactam if susceptible, carbapenems for severe or ESBL infections, amikacin in combination, colistin or tigecycline for carbapenem-resistant strains."],"dp":[]},"bacterio1-enterobacteria-2:e8":{"s":3,"u":["Proteus: swarming, urease +, non-lactose fermenter.","Proteus mirabilis , P. vulgaris and P. penneri are Gram-negative, non-capsulated bacilli (1-3 µm) with very high motility , producing a characteristic swarming film over blood agar; non-lactose fermenters on MacConkey; catalase and nitrate positive, oxidase negative, and strongly urease positive .","Note: one slide lists Proteus as spore-forming and glucose-negative; like all Enterobacteriaceae, Proteus does not form spores and ferments glucose."],"dp":[]},"bacterio1-enterobacteria-2:e9":{"s":3,"u":["Urease → alkaline urine → struvite stones, catheter blockage.","Virulence: urease splits urea to ammonia, making the urine alkaline and precipitating magnesium ammonium phosphate: struvite (infection) stones and catheter encrustation; flagella and swarming favour ascending UTI; fimbriae, biofilm , haemolysins, proteases and LPS."],"dp":[]}},"meta":{"1dvhmzh":{"a":"recall","vg":"bacterio1-enterobacteria-2:e0/recall/1"},"xqwrr9":{"a":"recall","vg":"bacterio1-enterobacteria-2:e8/recall/1"},"d8kxbj":{"a":"recall","vg":"bacterio1-enterobacteria-2:e1/recall/1"},"iymyvn":{"a":"relationship","vg":"bacterio1-enterobacteria-2:e1/relationship/1"},"12b8z1a":{"a":"recall","vg":"bacterio1-enterobacteria-2:e2/recall/1"},"138xbhp":{"a":"recall","vg":"bacterio1-enterobacteria-2:e2/recall/2"},"19ebp51":{"a":"recall","vg":"bacterio1-enterobacteria-2:e3/recall/1"},"pfeofc":{"a":"recall","vg":"bacterio1-enterobacteria-2:e4/recall/1"},"1hv9tad":{"a":"recall","vg":"bacterio1-enterobacteria-2:e5/recall/1"},"bqdppo":{"a":"recall","vg":"bacterio1-enterobacteria-2:e7/recall/1"},"efr5xx":{"a":"recall","vg":"bacterio1-enterobacteria-2:e6/recall/1"},"1sxzda9":{"a":"recall","vg":"bacterio1-enterobacteria-2:e8/recall/2"},"7yop8u":{"a":"recall","vg":"bacterio1-enterobacteria-2:e9/recall/1"},"h5n407":{"a":"recall","vg":"bacterio1-enterobacteria-2:e9/recall/2"},"1esrv6a":{"a":"recall","vg":"bacterio1-enterobacteria-2:e8/recall/3"}},"explRev":"ec464b822c34"};
